#!/usr/bin/env node
/**
 * Prepares generated docs content before VitePress runs:
 *
 * 1. Generates the TypeDoc API reference into `docs/api/` (with the
 *    VitePress sidebar JSON used by `docs/.vitepress/config.ts`). The run is
 *    skipped when `src/`, `typedoc.json` and `tsconfig.json` are unchanged.
 * 2. Copies `CHANGELOG.md` to `docs/changelog.md` with YAML frontmatter so
 *    both VitePress and Obsidian read it as a proper page/property.
 *
 * Both outputs are gitignored and regenerated by `bun run dev` /
 * `bun run deploy`.
 */
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const API_DIR = join(ROOT, "docs", "api");
const API_INDEX = join(API_DIR, "index.md");
const API_SIDEBAR = join(API_DIR, "typedoc-sidebar.json");
const API_HASH = join(API_DIR, ".cache-hash");
const TYPEDOC_BIN = join(ROOT, "node_modules", ".bin", "typedoc");

/** Hashes `src/**` + the TypeDoc/TS config so TypeDoc only runs when needed. */
function sourcesHash() {
	const hash = createHash("sha256");
	for (const file of ["typedoc.json", "tsconfig.json", "scripts/typedoc-drop-deprecated.mjs"]) {
		hash.update(readFileSync(join(ROOT, file)));
	}

	const walk = (dir) => {
		const entries = readdirSync(dir, { withFileTypes: true }).sort((a, b) =>
			a.name.localeCompare(b.name),
		);
		for (const entry of entries) {
			const full = join(dir, entry.name);
			if (entry.isDirectory()) {
				walk(full);
			} else if (entry.name.endsWith(".ts")) {
				hash.update(relative(ROOT, full));
				hash.update(readFileSync(full));
			}
		}
	};
	walk(join(ROOT, "src"));

	return hash.digest("hex");
}

const hash = sourcesHash();
const isCached =
	existsSync(API_INDEX) &&
	existsSync(API_SIDEBAR) &&
	existsSync(API_HASH) &&
	readFileSync(API_HASH, "utf8").trim() === hash;

if (isCached) {
	console.log("docs: docs/api/ is up to date (TypeDoc skipped)");
} else {
	if (!existsSync(TYPEDOC_BIN)) {
		console.error("docs: TypeDoc is not installed — run `bun install` first.");
		process.exit(1);
	}
	try {
		execFileSync(TYPEDOC_BIN, [], { cwd: ROOT, stdio: "inherit" });
	} catch {
		console.error(
			"docs: TypeDoc failed. If it mentions docs/.vitepress/.temp, stop `bun run dev` and retry.",
		);
		process.exit(1);
	}
	writeFileSync(API_HASH, hash);
	console.log("docs: generated docs/api/");
}

const changelog = readFileSync(join(ROOT, "CHANGELOG.md"), "utf8")
	.replace(/^# Changelog\n+/, "")
	.replace(
		/^## \[([^\]]+)\] - (\d{4}-\d{2}-\d{2})[ \t]*$/gm,
		(_, version, date) =>
			`<a id="v${version.replace(/\./g, "-")}"></a>\n\n## [${version}] - ${date}`,
	)
	.replace(/^- \[ \] (.+)$/gm, "- ☒ **$1**");

const page = [
	"---",
	"title: Changelog",
	"description: Release history for KatanaKit JS.",
	"---",
	"",
	"# Changelog",
	"",
	changelog,
].join("\n");

const tempPage = `${join(ROOT, "docs", ".changelog.md.tmp")}`;
writeFileSync(tempPage, page);
renameSync(tempPage, join(ROOT, "docs", "changelog.md"));
console.log("docs: wrote docs/changelog.md");

/* ──────────────────────────────────────────────────────────────────────────
 * 3. Build-time signals for the VitePress theme (`theme/signals.json`):
 *    navbar version pill, GitHub stars, sidebar `new` pills and the
 *    bottom-right "What's new" changelog panel. Every field degrades to a
 *    null/empty value instead of failing the build.
 * ──────────────────────────────────────────────────────────────────────── */

const SIGNALS_FILE = join(ROOT, "docs", ".vitepress", "theme", "signals.json");

/**
 * Link schemes allowed in generated HTML. The input is CHANGELOG bullets,
 * which come verbatim from commit subjects, so anything that can run script
 * (`javascript:`, `data:`) must never reach an `href` that is rendered with
 * `v-html` in the "What's new" panel.
 */
const SAFE_LINK = /^(https?:\/\/|mailto:|\/|#)/i;

function markdownToHtml(text) {
	return text
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;")
		.replace(/"/g, "&quot;")
		.replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (match, label, href) =>
			// Unsafe or unparseable target: keep the text, drop the link.
			SAFE_LINK.test(href.trim()) ? `<a href="${href.trim()}">${label}</a>` : label,
		)
		.replace(/`([^`]+)`/g, "<code>$1</code>")
		.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
}

/** Commit type → emoji used by the "What's new" panel bullets. */
const EMOJI_BY_TYPE = {
	feat: "\u{1F680}",
	fix: "\u{1F41B}",
	perf: "\u26A1",
	refactor: "\u267B\uFE0F",
	docs: "\u{1F4DA}",
	test: "\u{1F9EA}",
	build: "\u{1F4E6}",
	ci: "\u{1F916}",
	chore: "\u{1F9F9}",
	style: "\u{1F484}",
	release: "\u{1F389}",
	deps: "\u2B06\uFE0F",
	revert: "\u21A9\uFE0F",
};

/** `**scope:** …` bullets (writeChangelog format) → emoji by scope. */
const EMOJI_BY_SCOPE = {
	docs: "\u{1F4DA}",
	guides: "\u{1F4DA}",
	readme: "\u{1F4D6}",
	agents: "\u{1F9E0}",
	changelog: "\u{1F4DD}",
	contributing: "\u{1F4DD}",
	ci: "\u{1F916}",
	workflows: "\u{1F4E1}",
	scripts: "\u{1F4E1}",
	release: "\u{1F389}",
	test: "\u{1F9EA}",
	tests: "\u{1F9EA}",
	ui: "\u{1F3A8}",
	css: "\u{1F3A8}",
	theme: "\u{1F3A8}",
	vitepress: "\u{1F4D9}",
	".vitepress": "\u{1F4D9}",
	deps: "\u2B06\uFE0F",
	"bun.lock": "\u2B06\uFE0F",
	lock: "\u2B06\uFE0F",
	security: "\u{1F512}",
	faker: "\u{1F3B2}",
	photoswipe: "\u{1F5BC}\uFE0F",
	adapters: "\u{1F9E9}",
	astro: "\u2604\uFE0F",
	express: "\u{1F310}",
	nuxt: "\u{1F310}",
	vue: "\u{1F310}",
	react: "\u{1F310}",
	http: "\u{1F310}",
	query: "\u{1F9E9}",
	core: "\u2699\uFE0F",
	config: "\u2699\uFE0F",
	infrastructure: "\u{1F527}",
	types: "\u{1F4DC}",
	katanakit: "\u{1F4E6}",
	"katanakit-js": "\u{1F4E6}",
	"katanakit-css": "\u{1F3A8}",
};

/** Last-resort read of the sentence when neither the type nor the scope helps. */
const KEYWORD_EMOJI = [
	[/\b(fix(es|ed)?|bug|patch|typo)\b/i, "\u{1F41B}"],
	[/\b(remove|drop|delet|deprecat)\b/i, "\u{1F5D1}\uFE0F"],
	[/\b(security|secret|token|csrf|xss)\b/i, "\u{1F512}"],
	[/\b(perf(ormance)?|faster|speed|optimi)\b/i, "\u26A1"],
	[/\b(deps?|dependenc(?:y|ies)?|bump|upgrade|lock(?:file)?|install)\b/i, "\u2B06\uFE0F"],
	[/\b(test|vitest|spec|coverage)\b/i, "\u{1F9EA}"],
	[/\b(docs?|guides?|readme|changelog)\b/i, "\u{1F4DA}"],
	[/\b(ci|workflow|pipeline|actions)\b/i, "\u{1F916}"],
	[/\b(release|publish|version)\b/i, "\u{1F389}"],
	[/\b(lint|prettier|format|eslint)\b/i, "\u{1F9F9}"],
	[/\b(hook|husky|lint-staged|commit)\b/i, "\u{1F511}"],
	[/\b(add(s|ed)?|new|introduc|support)\b/i, "\u2728"],
];

/**
 * Emoji for one changelog bullet, resolved in three passes so the panel never
 * renders a bare `✨` when the sentence says what happened:
 * conventional type → `**scope:**`/`type(scope)` scope → keyword read.
 */
function emojiFor(text) {
	const type = /^(\w+)(?:\([^)]*\))?!?:/.exec(text)?.[1];
	if (type && EMOJI_BY_TYPE[type]) return EMOJI_BY_TYPE[type];

	const scope = (
		// matches both `**scope:**` (writeChangelog) and `**scope**:` variants
		/^\*\*([^*]+?)(?::\*\*|\*\*:)/.exec(text)?.[1] ??
		/^[a-z][\w-]*\(([^)]+)\)/.exec(text)?.[1] ??
		""
	)
		.trim()
		.toLowerCase();
	if (EMOJI_BY_SCOPE[scope]) return EMOJI_BY_SCOPE[scope];

	for (const [pattern, emoji] of KEYWORD_EMOJI) {
		if (pattern.test(text)) return emoji;
	}
	return "\u2728";
}

/**
 * The last 6 releases (or the last 3 when fewer than 6 exist), each reduced to
 * its bullet summary with an emoji per bullet — what the bottom-right panel shows.
 */
function recentReleases() {
	const text = readFileSync(join(ROOT, "CHANGELOG.md"), "utf8");
	const headings = [...text.matchAll(/^## \[([^\]]+)\] - (\d{4}-\d{2}-\d{2})[ \t]*$/gm)];
	const releases = [];

	for (let index = 0; index < headings.length && releases.length < 6; index++) {
		const heading = headings[index];
		const body = text.slice(
			heading.index + heading[0].length,
			index + 1 < headings.length ? headings[index + 1].index : text.length,
		);

		const items = [];
		for (const rawLine of body.split(/\r?\n/)) {
			const line = rawLine.trimEnd();
			if (!/^-\s+/.test(line)) continue;
			const bullet = line.replace(/^-\s+/, "").replace(/^\[ \]\s*/, "");
			items.push({ emoji: emojiFor(bullet), html: `<strong>${markdownToHtml(bullet)}</strong>` });
		}
		if (items.length > 0) {
			releases.push({ version: heading[1], date: heading[2], items });
		}
	}

	const take = releases.length >= 6 ? 6 : Math.min(3, releases.length);
	return releases.slice(0, take);
}

/** Docs pages changed in the current release cycle, as site routes. */
function newPagePaths() {
	const run = (...args) => {
		try {
			return execFileSync("git", args, {
				cwd: ROOT,
				encoding: "utf8",
				maxBuffer: 32 * 1024 * 1024,
			});
		} catch {
			return "";
		}
	};

	const tags = run("tag", "--sort=-v:refname")
		.split("\n")
		.map((tag) => tag.trim())
		.filter((tag) => /^v\d+\.\d+\.\d+$/.test(tag));
	// Badges cover what the reader has not seen yet: pages added since the
	// *previous* release tag, so a page the newest release just shipped keeps
	// its "new" pill until the next release retires it. `-M` collapses the
	// moves a migration/revert produces into renames, and the filter keeps only
	// `A` (added), so an edit to an existing page or a pure move never shows a
	// "new" pill. HEAD is what is shipping.
	const base = tags[1] ?? tags[0];
	const range = base ? `${base}..HEAD` : "";
	if (range) {
		const check = run("rev-parse", "--verify", "--quiet", `${base}^{commit}`);
		if (!check) {
			console.warn(`docs: baseline ${base} is not available (shallow clone?); new-page badges may be incomplete`);
		}
	}
	const tracked = range
		? run("diff", "-M", "--name-only", "--diff-filter=A", range, "--", "docs")
		: run("log", "-1", "--name-only", "--diff-filter=A", "--pretty=format:", "--", "docs");
	const untracked = run("ls-files", "--others", "--exclude-standard", "--", "docs");

	const pages = new Set();
	for (const line of `${tracked}\n${untracked}`.split("\n")) {
		const file = line.trim();
		if (!file.startsWith("docs/") || !/\.mdx?$/.test(file)) continue;
		if (file.includes("/.vitepress/") || file.includes("/public/")) continue;
		if (!existsSync(join(ROOT, file))) continue;
		let route = `/${file.slice("docs/".length).replace(/\.mdx?$/, "")}`;
		if (route.endsWith("/index")) route = route.slice(0, -"index".length);
		if (route.length > 1 && route.endsWith("/")) route = route.slice(0, -1);
		pages.add(route || "/");
	}
	pages.delete("/changelog");
	return [...pages].sort();
}

/** Star count, fetched once per build so the site never hits the API. */
async function githubStars() {
	try {
		const response = await fetch("https://api.github.com/repos/senseikatana/katanakit-js", {
			headers: { Accept: "application/vnd.github+json", "User-Agent": "katanakit-docs-build" },
			signal: AbortSignal.timeout(6_000),
		});
		if (response.ok) {
			const data = await response.json();
			if (typeof data.stargazers_count === "number") return data.stargazers_count;
		}
	} catch {
		/* offline or rate-limited — the badge stays hidden */
	}
	return null;
}

/** Version shown in the navbar pill: the newest tag wins over package.json. */
function releasedVersion() {
	try {
		const tag = execFileSync("git", ["tag", "--sort=-v:refname"], { cwd: ROOT, encoding: "utf8" })
			.split("\n")
			.map((line) => line.trim())
			.find((line) => /^v\d+\.\d+\.\d+$/.test(line));
		if (tag) return tag.slice(1);
	} catch {
		/* fall through to package.json */
	}
	return JSON.parse(readFileSync(join(ROOT, "package.json"), "utf8")).version;
}

/**
 * Version groups for the navbar releases flyout (Bootstrap-style): the latest
 * release, recent releases of the current major, and the newest release of
 * every older major, linked to its upgrade guide when one exists.
 */
function releaseVersions() {
	const text = readFileSync(join(ROOT, "CHANGELOG.md"), "utf8");
	const releases = [...text.matchAll(/^## \[([^\]]+)\] - (\d{4}-\d{2}-\d{2})[ \t]*$/gm)].map(
		(match) => ({
			version: match[1],
			date: match[2],
			// VitePress slug for `## [6.7.5] - 2026-10-04` → `_6-7-5-2026-10-04`.
			anchor: `#_${match[1].replace(/\./g, "-")}-${match[2]}`,
		}),
	);
	if (releases.length === 0) return null;

	const [latest] = releases;
	const currentMajor = latest.version.split(".")[0];
	const recent = releases
		.filter((release) => release.version.split(".")[0] === currentMajor)
		.slice(0, 5);

	const previous = [];
	for (const release of releases) {
		const major = release.version.split(".")[0];
		if (major === currentMajor || previous.some((entry) => entry.major === major)) continue;
		const guide = join(ROOT, "docs", "guides", "upgrade-to", `v${major}.md`);
		previous.push({
			major,
			version: release.version,
			date: release.date,
			anchor: release.anchor,
			link: existsSync(guide) ? `/guides/upgrade-to/v${major}` : "/changelog",
		});
		if (previous.length === 4) break;
	}

	return { latest, recent, previous };
}

/** Shape consumed by the What's new panel: latest release + its summary list. */
function recentChangelog() {
	const releases = recentReleases();
	if (releases.length === 0) return null;
	return { version: releases[0].version, date: releases[0].date, releases };
}

const signals = {
	version: releasedVersion(),
	stars: await githubStars(),
	newPages: newPagePaths(),
	changelog: recentChangelog(),
	versions: releaseVersions(),
};

mkdirSync(dirname(SIGNALS_FILE), { recursive: true });
writeFileSync(SIGNALS_FILE, `${JSON.stringify(signals, null, "\t")}\n`);
console.log(
	`docs: signals → version ${signals.version}, stars ${signals.stars ?? "n/a"}, ` +
		`${signals.newPages.length} new page(s)${signals.changelog ? `, changelog v${signals.changelog.version}` : ""}` +
		`${signals.versions ? `, ${signals.versions.previous.length} previous major(s)` : ""}`,
);
